<template>
  <section class="page-stack wide-workspace"><header class="page-heading"><span class="kicker">Policy Validation</span><h1>策略验证</h1><p>管理冻结验证集、显式运行验证，并查看版本注册状态。</p></header><p v-if="error" class="inline-notice danger" role="alert">{{ error }}</p><p v-if="notice" class="inline-notice" role="status">{{ notice }}</p>
    <div class="panel-grid two"><form class="form-panel compact-form" @submit.prevent="create"><h2>创建验证集</h2><label>名称<input v-model="name" required /></label><label>版本<input v-model="version" required /></label><button class="primary-button">创建</button></form><form class="form-panel compact-form" @submit.prevent="add"><h2>添加 PolicyDecision</h2><label>Dataset ID<input v-model="datasetId" required /></label><label>Decision ID<input v-model="decisionId" required /></label><button class="secondary-button">添加</button></form></div>
    <section class="workspace-panel"><div class="section-heading"><div><h2>冻结并运行</h2><p>冻结和运行均为显式操作。</p></div></div><div class="inline-form"><label>Dataset ID<input v-model="datasetId" /></label><button class="secondary-button danger" :disabled="!datasetId" @click="confirmFreeze=true">冻结</button><button class="primary-button" :disabled="!datasetId" @click="run">运行验证</button></div><article v-if="report" class="surface-card"><h3>最新验证报告</h3><StatusBadge :status="String(report.promotion_status||'review_required')"/><JsonDetails :value="report"/></article></section>
    <section class="workspace-panel"><div class="section-heading"><div><h2>Validation registry</h2><p>状态由后端验证运行决定。</p></div><button class="secondary-button" @click="loadRegistry">刷新</button></div><AsyncState :loading="loading" :error="registryError" :empty="registry.length===0" empty-title="暂无 registry 记录" @retry="loadRegistry"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Policy</th><th>Rules</th><th>状态</th><th>Latest run</th><th>原因</th></tr></thead><tbody><tr v-for="row in registry" :key="`${row.policy_version}-${row.rules_version}`"><td>{{ row.policy_version }}</td><td>{{ row.rules_version }}</td><td><StatusBadge :status="row.validation_status"/></td><td>{{ row.latest_validation_run_id||row.latest_run_id||'—' }}</td><td><span v-for="code in row.reason_codes" :key="code" class="reason-inline">{{ explainReasonCode(code) }} <code>{{ code }}</code></span></td></tr></tbody></table></div></AsyncState></section>
    <ConfirmDialog :open="confirmFreeze" title="冻结验证数据集？" message="冻结后不能继续添加决策；请确认数据集内容完整。" confirm-label="确认冻结" danger @cancel="confirmFreeze=false" @confirm="freeze" />
  </section>
</template>
<script setup lang="ts">
import { onMounted,ref } from 'vue'; import { policyValidationApi } from '@/api/policyValidation'; import AsyncState from '@/components/common/AsyncState.vue'; import ConfirmDialog from '@/components/common/ConfirmDialog.vue'; import JsonDetails from '@/components/common/JsonDetails.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import { explainReasonCode } from '@/utils/reasonCodes'; import type { JsonObject,RegistryEntry } from '@/types/professional'
const name=ref(''),version=ref('policy-validation-v1'),datasetId=ref(''),decisionId=ref(''),registry=ref<RegistryEntry[]>([]),report=ref<JsonObject|null>(null),loading=ref(true),registryError=ref(''),error=ref(''),notice=ref(''),confirmFreeze=ref(false); const msg=(e:unknown)=>e instanceof Error?e.message:'操作失败'
async function create(){try{const r=await policyValidationApi.createDataset(name.value,version.value);datasetId.value=r.id;notice.value='验证集已创建。'}catch(e){error.value=msg(e)}} async function add(){try{await policyValidationApi.addDecision(datasetId.value,decisionId.value);notice.value='决策已加入验证集。'}catch(e){error.value=msg(e)}} async function freeze(){try{await policyValidationApi.freeze(datasetId.value);confirmFreeze.value=false;notice.value='验证集已冻结。'}catch(e){error.value=msg(e)}} async function run(){try{report.value=await policyValidationApi.run(datasetId.value);notice.value='验证运行完成。';await loadRegistry()}catch(e){error.value=msg(e)}} async function loadRegistry(){loading.value=true;registryError.value='';try{registry.value=await policyValidationApi.registry()}catch(e){registryError.value=msg(e)}finally{loading.value=false}} onMounted(loadRegistry)
</script>
